public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    if (buffer.total() != buffer.safeLimit()) {
        throw new IOException("Buffer not empty after serialization");
    }
    if (buffer != buffer) {
        throw new IllegalArgumentException("buffer can't be null");
    }
    buffer.clear();
    if (size > 1 << 28 - 1) {
        throw new IOException("Message is too large to write");
    }
    if (Utilities.writeZigZag32(out, size) != size) {
        throw new IOException("Failed to write message size");
    }
    if (Utilities.writeRawBytes(out, data, 0, data.length) != data.length) {
        throw new IOException("Failed to write message");
    }
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    out.write(CodedOutputStream.computeRawVarint32Size(size));
    CodedOutputStream.writeRawVarint32ToBuffer(size, buffer);
    out.write(data, 0, size);
    return size;
}

int function(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    ByteString byteString = ByteString.copyFrom(data);
    int size = byteString.size();
    out.write(CodedOutputStream.computeRawVarint32Size(size));
    CodedOutputStream codedOutputStream = CodedOutputStream.newInstance(out, buffer);
    codedOutputStream.writeRawVarint32(size);
    codedOutputStream.writeRawBytes(byteString.toByteArray());
    codedOutputStream.flush();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(data, 0, size);
    return size + 4;
}

int function(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    ByteBuffer header = ByteBuffer.allocate(4).putInt(data.length);
    header.flip();
    out.write(header.array());
    out.write(data, 0, data.length);
    return data.length;
}

