static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayInBucket = (int) (timeBucket % 100);
    int adjustedDay = dayInBucket - dayInBucket % dayStep + (dayInBucket % dayStep >= dayStep / 2 ? dayStep : 0);
    return timeBucket - dayInBucket + adjustedDay;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    if (dayStep == 0) {
        return timeBucket;
    }

    int daysToSubtract;

    if (month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) {
        daysToSubtract = 30 + dayStep - day;
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        daysToSubtract = 31 + dayStep - day;
    } else {
        // Assume it's February
        daysToSubtract = 28 + dayStep - day;
    }

    if (daysToSubtract > 0) {
        if (day - daysToSubtract <= 0) {
            month--;
            if (month == 0) {
                month = 12;
                year--;
            }
        }
        day = day - daysToSubtract;
    }

    if (month == 0) {
        month = 12;
        year--;
    }

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    if (dayOfMonth <= dayStep) {
        dayOfMonth = dayStep;
    } else {
        dayOfMonth -= dayStep;
    }

    return year * 10000 + month * 100 + dayOfMonth;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 0) {
        throw new IllegalArgumentException("dayStep cannot be zero");
    }

    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    if (day <= dayStep) {
        return (year * 100L + month) * 100L + 1;
    } else {
        long newDay = ((day - dayStep - 1) / 7) * 7 + 1;
        return (year * 100L + month) * 100L + newDay;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = Math.min(index + len, str.length());
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            if (Character.isHighSurrogate(ch) && (i + 1) < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                i++;
                size += 4;
            } else {
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

