    int totalSize = 0;
    byte[] buffer = node.getBuffer();
    int length = node.getSize();

    out.writeInt(length);
    out.write(buffer, 0, length);
    totalSize += length + 4;

    while (node.getNext() != null) {
        node = node.getNext();
        buffer = node.getBuffer();
        length = node.getSize();

        out.writeInt(length);
        out.write(buffer, 0, length);
        totalSize += length + 4;
    }

    return totalSize;
}

