public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = Math.max(desiredCapacity, desiredCapacity + 1);
    while (!isPrime(candidate)) {
        candidate++;
    }
    if (desiredCapacity >= 1000 && candidate - desiredCapacity > 0.11 * desiredCapacity) {
        candidate--;
        while (!isPrime(candidate)) {
            candidate--;
        }
    }
    return candidate;
}

