    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
            if (desiredCapacity >= 1000 && capacity - desiredCapacity > 0.11 * desiredCapacity) {
                break outerLoop;
            }
        }
    }

    return capacity;
}

