    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edgeSet()) {
        int source = edge.getSource();
        int target = edge.getTarget();

        Set<Integer> sourceNeighbors = graph.neighbors(source);
        Set<Integer> targetNeighbors = graph.neighbors(target);

        Set<Integer> commonNeighbors = new HashSet<>(sourceNeighbors);
        commonNeighbors.retainAll(targetNeighbors);

        Set<Integer> minimalSeparators = new HashSet<>();
        for (int neighbor : commonNeighbors) {
            if (neighbor != source && neighbor != target) {
                minimalSeparators.add(neighbor);
            }
        }

        List<Pair<Integer,Integer>> minimalSeparatorList = new ArrayList<>();
        for (int separator : minimalSeparators) {
            minimalSeparatorList.add(new Pair<>(source, separator));
            minimalSeparatorList.add(new Pair<>(target, separator));
        }

        globalSeparatorList.add(new Pair<>(minimalSeparatorList, edge));
    }

    return globalSeparatorList;
}

