    if (vertices.isEmpty()) {
        return true;
    }

    Set<V> verticesCopy = new HashSet<>(vertices);

    while (!verticesCopy.isEmpty()) {
        V vertex = verticesCopy.iterator().next();
        verticesCopy.remove(vertex);

        for (V otherVertex : verticesCopy) {
            if (!graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }

    return true;
}

