    if (vertices == null || vertices.isEmpty()) {
        return true; // An empty graph or no vertices means it's trivially a clique
    }

    Set<V> vertexSet = graph.vertexSet();
    if (!vertexSet.containsAll(vertices)) {
        throw new IllegalArgumentException("Vertices not all in graph");
    }

    for (V vertex : vertices) {
        Set<V> neighbors = graph.adjacentVertices(vertex);
        if (!vertices.containsAll(neighbors)) {
            return false; // If any vertex has a neighbor not in vertices, it's not a clique
        }
    }

    return true;
}

